SELECT
    log_id,
    employee_id,
    resource_type,
    resource_id,
    project_id,
    action,
    decision,
    trigger_policy,
    deny_reason,
    project_phase,
    assets_stage,
    security_level,
    request_ip,
    request_uri,
    request_time,
    detail_json
FROM audit_logs


        AND employee_id = #{employeeId}


        AND resource_type = #{resourceType}


        AND resource_id = #{resourceId}


        AND project_id = #{projectId}


        AND action = #{action}


        AND decision = #{decision}


        AND security_level = #{securityLevel}


        AND request_time >= #{startTime}


        AND request_time <= #{endTime}


ORDER BY request_time DESC, log_id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM audit_logs


        AND employee_id = #{employeeId}


        AND resource_type = #{resourceType}


        AND resource_id = #{resourceId}


        AND project_id = #{projectId}


        AND action = #{action}


        AND decision = #{decision}


        AND security_level = #{securityLevel}


        AND request_time >= #{startTime}


        AND request_time <= #{endTime}

SELECT COUNT(*)
FROM audit_logs
WHERE employee_id = #{employeeId}
  AND action = #{action}
  AND decision = 'ALLOW'
  AND request_time >= #{startTime}

  AND resource_type = #{resourceType}
